('case-063', 'own-success', 'invocation', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', 'SBaI0/3QhLM=', 'B+HATqBSCGQ=', 'workflow.execute', 0, 1, '/.well-known/workflow/v1/flow', 'unknown_error', '', ['{"trace_id":"YFb9TR8F393paYF3xZIBzg==","span_id":"fW9TlQ8Ss5I="}']),
('case-063', 'own-success', 'wrapper', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', 'xl3GMnMgpik=', 'SBaI0/3QhLM=', 'workflow.replay.load', 0, 2, '/.well-known/workflow/v1/flow', 'unknown_error', '', []),
('case-063', 'own-success', 'sdk', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', 'so9mk2me2cM=', 'xl3GMnMgpik=', 'world.events.create run_started', 0, 2, '/.well-known/workflow/v1/flow', 'unknown_error', '', []),
('case-063', 'own-success', 'http', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', 'j8sMeuo8Tmw=', 'so9mk2me2cM=', 'http POST', 0, 2, '/.well-known/workflow/v1/flow', 'HTTP 410', '410', []),
('case-063', 'own-success', 'transport', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', 'ADb2NzJGzq8=', 'SBaI0/3QhLM=', 'workflow.events.ws.connect', 0, 2, '/.well-known/workflow/v1/flow', 'TRANSPORT', '', []),
('case-063', 'own-success-delivery', 'queue', 'mikka-web', 'YFb9TR8F393paYF3xZIBzg==', 'fW9TlQ8Ss5I=', 'ryntQ4smP/s=', 'vqs.process', 0, 0, '/.well-known/workflow/v1/flow', 'unknown_error', '', []),
('case-063', 'own-success', 'other-root', 'mikka-web', 'PxfKX6VCIxi0XWotkGzJNA==', '52LM7Ep1rcY=', '', 'unrelated.root', 1, 2, '/api/rpc', 'REAL_ROOT_FAILURE', '', []),
('case-064', 'historical-linked', 'delivery', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'B3nopVsjnx4=', '0UoP/USKHaU=', 'workflow.route.flow', 1, 1, '/.well-known/workflow/v1/flow', 'unknown_error', '200', []),
('case-064', 'historical-linked', 'invocation', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'oW+kDJLmDJU=', 'toDnotqhW+8=', 'workflow.execute', 0, 1, '/.well-known/workflow/v1/flow', 'unknown_error', '', ['{"trace_id":"EI0FsWBWwGfYakt2KIFFhg==","span_id":"K7eZpV2kK+I="}']),
('case-064', 'historical-linked', 'wrapper', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'jtfYPkiE28w=', 'oW+kDJLmDJU=', 'workflow.replay.load', 0, 2, '/.well-known/workflow/v1/flow', 'unknown_error', '', []),
('case-064', 'historical-linked', 'sdk', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'dvOOVhJVOKQ=', 'jtfYPkiE28w=', 'world.events.create run_started', 0, 2, '/.well-known/workflow/v1/flow', 'unknown_error', '', []),
('case-064', 'historical-linked', 'http', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'kJQJaK2SXQM=', 'dvOOVhJVOKQ=', 'http POST', 0, 2, '/.well-known/workflow/v1/flow', 'HTTP 410', '410', []),
('case-064', 'historical-linked', 'transport', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', '0oRGaZeLOjw=', 'oW+kDJLmDJU=', 'workflow.events.ws.connect', 0, 2, '/.well-known/workflow/v1/flow', 'TRANSPORT', '', []),
('case-064', 'historical-linked', 'queue', 'mikka-web', 'SyW9H6RU7pmR7MgPVFCrpg==', 'toDnotqhW+8=', 'B3nopVsjnx4=', 'vqs.process', 0, 0, '/.well-known/workflow/v1/flow', 'unknown_error', '', [])]) AS r),
    fixture_source AS (
        SELECT evaluated_hour AS timestamp, r.4 AS service_name, r.5 AS trace_id, r.6 AS span_id,
            r.7 AS parent_span_id, r.8 AS name, r.9 AS is_root_span, r.10 AS status_code, r.14 AS links,
            map('mikka.route', r.11, 'mikka.error.code', r.12, 'http.response.status_code', r.13) AS attributes,
            map('deployment.environment.name', 'production') AS resource_attributes
        FROM fixture_rows
    ),
    workflow_spans AS (
        SELECT raw.service_name, raw.trace_id, raw.span_id, raw.parent_span_id, raw.links,
            CASE WHEN raw.name LIKE 'workflow.execute %' THEN 'workflow.execute'
                 WHEN raw.name LIKE 'workflow.run %' THEN 'workflow.run'
                 WHEN raw.name LIKE 'step.execute %' THEN 'step.execute' ELSE raw.name END AS name,
            raw.status_code,
            toFloatOrNull(raw.attributes['http.response.status_code']) AS http_status,
            coalesce(nullIf(raw.attributes['mikka.route'], ''), 'unknown') AS route,
            coalesce(nullIf(raw.attributes['mikka.error.code'], ''), nullIf(raw.attributes['error.type'], ''), 'unknown_error') AS error_code
        FROM fixture_source raw
        WHERE raw.timestamp >= evaluated_hour - INTERVAL 8 DAY AND raw.timestamp < evaluated_hour + INTERVAL 1 HOUR
          AND raw.service_name = 'mikka-web'
          AND (raw.resource_attributes['deployment.environment.name'] = 'production' OR raw.resource_attributes['deployment.environment'] = 'production')
          AND (raw.name IN (
              'workflow.route.flow', 'vqs.process', 'workflow.execute', 'workflow.run', 'step.execute',
              'workflow.replay.load', 'after:workflow-wake', 'cron:reconcile', 'GET /api/cron/reconcile', 'hook.resume')
              OR raw.name LIKE 'workflow.execute %' OR raw.name LIKE 'workflow.run %' OR raw.name LIKE 'step.execute %'
              OR raw.status_code = 2 AND raw.name IN (
                  'http GET', 'http POST', 'world.hooks.getByToken',
                  'world.events.create wait_created', 'world.events.create wait_completed', 'world.events.create step_started',
                  'world.events.create run_started', 'world.events.create hook_received'))
    ),
    workflow_traces AS (
        -- Finite node tuple: id, parent, name, route, error, HTTP status, span status, links.
        -- Keep non-root entries. Success elsewhere in a trace is never an attempt's proof.
        SELECT service_name, trace_id,
            groupArray((span_id, parent_span_id, name, route, error_code, http_status, status_code, links)) AS nodes
        FROM workflow_spans GROUP BY service_name, trace_id
    ),
    delivery_contexts AS (
        -- A queue context proves only its exact successful flow parent, never its own origin link.
        SELECT DISTINCT service_name, trace_id,
            arrayJoin(arrayMap(d -> d.1, arrayFilter(d -> d.7 IN (0, 1) AND d.5 = 'unknown_error' AND (
                d.3 = 'workflow.route.flow' AND d.4 = '/.well-known/workflow/v1/flow' AND d.6 >= 200 AND d.6 < 300
                OR d.3 = 'vqs.process' AND arrayExists(f -> f.1 = d.2 AND f.3 = 'workflow.route.flow'
                    AND f.4 = '/.well-known/workflow/v1/flow' AND f.7 IN (0, 1) AND f.5 = 'unknown_error'
                    AND f.6 >= 200 AND f.6 < 300, nodes)), nodes))) AS span_id
        FROM workflow_traces
    ),
    invocations AS (
        SELECT service_name, trace_id,
            arrayJoin(arrayFilter(i -> i.3 = 'workflow.execute' AND i.7 IN (0, 1) AND i.5 = 'unknown_error', nodes)) AS invocation
        FROM workflow_traces
    ),
    invocation_references AS (
        -- Linked: exact local parent. Continuous: one valid link to the delivery or its vqs.process.
        -- JSON link IDs already use the table's native base64 representation.
        SELECT service_name, trace_id, invocation.1 AS invocation_id,
            arrayJoin(arrayConcat([(trace_id, invocation.2)],
                if(length(invocation.8) = 1 AND isValidJSON(arrayElement(invocation.8, 1)),
                    [(JSONExtractString(arrayElement(invocation.8, 1), 'trace_id'), JSONExtractString(arrayElement(invocation.8, 1), 'span_id'))], []))) AS reference
        FROM invocations
    ),
    proven_invocations AS (
        -- Resolve cross-trace links once per invocation, not once per error/client/wrapper.
        SELECT i.service_name AS service_name, i.trace_id AS trace_id, groupUniqArray(i.invocation_id) AS ids
        FROM invocation_references i JOIN delivery_contexts d
          ON i.service_name = d.service_name AND tupleElement(i.reference, 1) = d.trace_id AND tupleElement(i.reference, 2) = d.span_id
        GROUP BY i.service_name, i.trace_id
    ),
    entry_proofs AS (
        SELECT t.service_name AS service_name, t.trace_id AS trace_id, t.nodes AS nodes,
            arrayFilter(n -> n.7 = 2, t.nodes) AS errors, coalesce(i.ids, []) AS invocation_ids,
            arrayMap(o -> o.1, arrayFilter(o -> o.7 IN (0, 1) AND o.5 = 'unknown_error'
                AND o.3 = 'after:workflow-wake' AND o.4 = 'after:workflow-wake', t.nodes)) AS wake_ids,
            arrayMap(o -> o.1, arrayFilter(o -> o.7 IN (0, 1) AND o.5 = 'unknown_error'
                AND o.3 = 'cron:reconcile' AND o.4 = 'cron:reconcile'
                AND arrayExists(e -> e.1 = o.2 AND e.3 = 'GET /api/cron/reconcile' AND e.4 = '/api/cron/reconcile'
                    AND e.7 IN (0, 1) AND e.5 = 'unknown_error' AND e.6 >= 200 AND e.6 < 300, t.nodes), t.nodes)) AS cron_ids,
            -- The inner step span starts before stepMetadata; its route can still be flow.
            -- Only its hook/SDK/client descendants must carry the exact closed nudge label.
            arrayMap(o -> o.1, arrayFilter(o -> o.7 IN (0, 1) AND o.5 = 'unknown_error' AND o.3 = 'step.execute', t.nodes)) AS step_ids
        FROM workflow_traces t LEFT JOIN proven_invocations i
          ON t.service_name = i.service_name AND t.trace_id = i.trace_id
    ),
    handled_attempts AS (
        SELECT service_name, trace_id, errors,
            arrayFilter(c -> arrayExists(p -> p.1 = c.2 AND p.5 = 'unknown_error' AND p.4 = c.4 AND (
                c.3 = 'http POST' AND c.4 = '/.well-known/workflow/v1/flow'
                AND (c.6 = 409 AND c.5 = 'HTTP 409' AND p.3 IN (
                    'world.events.create wait_created', 'world.events.create wait_completed', 'world.events.create step_started', 'world.events.create run_started')
                    OR c.6 = 410 AND c.5 = 'HTTP 410' AND p.3 = 'world.events.create run_started')
                AND (has(invocation_ids, p.2) OR arrayExists(w -> w.1 = p.2
                    AND w.3 IN ('workflow.replay.load', 'workflow.run', 'step.execute') AND has(invocation_ids, w.2), nodes))
                OR c.6 = 404 AND (
                    c.3 = 'http GET' AND c.5 = 'not-found' AND p.3 = 'world.hooks.getByToken'
                      AND c.4 IN ('cron:reconcile', 'after:workflow-wake', 'workflow:coordinatorWakeDeadline/nudgeWorkflow')
                    OR c.3 = 'http POST' AND c.5 = 'HTTP 404' AND p.3 = 'world.events.create hook_received'
                      AND c.4 = 'workflow:coordinatorWakeDeadline/nudgeWorkflow')
                AND (c.4 = 'cron:reconcile' AND has(cron_ids, p.2)
                    OR arrayExists(w -> w.1 = p.2 AND w.3 = 'hook.resume' AND w.4 = c.4 AND (
                        c.4 = 'after:workflow-wake' AND has(wake_ids, w.2)
                        OR c.4 = 'cron:reconcile' AND has(cron_ids, w.2)
                        OR c.4 = 'workflow:coordinatorWakeDeadline/nudgeWorkflow' AND has(step_ids, w.2)), nodes))
            ), errors), errors) AS clients
        FROM entry_proofs
    ),
    handled_parents AS (
        SELECT service_name, trace_id, errors, clients,
            arrayFilter(p -> has(arrayMap(c -> c.2, clients), p.1), errors) AS parents
        FROM handled_attempts
    ),
    handled_spans AS (
        SELECT service_name, trace_id,
            arrayJoin(arrayConcat(
                arrayMap(c -> c.1, clients),
                arrayMap(p -> p.1, parents),
                arrayMap(g -> g.1, arrayFilter(g -> g.5 = 'unknown_error' AND (
                    g.3 = 'hook.resume' AND arrayExists(p -> p.2 = g.1 AND p.3 IN ('world.hooks.getByToken', 'world.events.create hook_received'), parents)
                    OR g.3 = 'workflow.replay.load' AND arrayExists(p -> p.2 = g.1 AND p.3 = 'world.events.create run_started', parents)), errors))
            )) AS span_id
        FROM handled_parents
    ),
    baseline_workflow_spans AS (
        SELECT service_name, trace_id, span_id, parent_span_id, is_root_span, name, status_code,
            toFloatOrNull(attributes['http.response.status_code']) AS http_status,
            coalesce(nullIf(attributes['mikka.route'], ''), 'unknown') AS route,
            coalesce(nullIf(attributes['mikka.error.code'], ''), nullIf(attributes['error.type'], ''), 'unknown_error') AS error_code
        FROM fixture_source
        WHERE timestamp >= evaluated_hour - INTERVAL 8 DAY AND timestamp < evaluated_hour + INTERVAL 1 HOUR
          AND service_name = 'mikka-web'
          AND (resource_attributes['deployment.environment.name'] = 'production' OR resource_attributes['deployment.environment'] = 'production')
          AND (is_root_span OR status_code = 2 AND name IN (
              'http GET', 'http POST', 'world.hooks.getByToken', 'hook.resume', 'workflow.replay.load',
              'world.events.create wait_created', 'world.events.create wait_completed', 'world.events.create step_started',
              'world.events.create run_started', 'world.events.create hook_received'))
    ),
    baseline_workflow_traces AS (
        -- Keep ancestry in each trace so matching does not rescan the historical window.
        SELECT service_name, trace_id,
            groupArrayIf((span_id, parent_span_id, name, route, error_code, http_status), status_code = 2) AS errors
        FROM baseline_workflow_spans
        WHERE service_name = 'mikka-web'
        GROUP BY service_name, trace_id
        HAVING countIf(is_root_span AND (status_code = 2 OR http_status >= 400)) = 0
           AND countIf(is_root_span AND status_code != 2 AND (
               (name = 'workflow.route.flow' AND route = '/.well-known/workflow/v1/flow'
                OR name = 'GET /api/cron/reconcile' AND route = '/api/cron/reconcile')
               AND http_status >= 200 AND http_status < 300
               OR name = 'after:workflow-wake' AND route = 'after:workflow-wake')) > 0
    ),
    baseline_handled_attempts AS (
        -- Error tuple fields are span id, parent id, name, route, code and HTTP status.
        SELECT service_name, trace_id, errors,
            arrayFilter(c ->
                (c.3 = 'http POST' AND c.4 = '/.well-known/workflow/v1/flow'
                 AND (c.6 = 409 AND c.5 = 'HTTP 409' OR c.6 = 410 AND c.5 = 'HTTP 410')
                 OR c.3 = 'http GET' AND c.6 = 404 AND c.5 = 'not-found'
                    AND c.4 IN ('cron:reconcile', 'after:workflow-wake', 'workflow:coordinatorWakeDeadline/nudgeWorkflow')
                 OR c.3 = 'http POST' AND c.6 = 404 AND c.5 = 'HTTP 404'
                    AND c.4 = 'workflow:coordinatorWakeDeadline/nudgeWorkflow')
                AND arrayExists(p -> p.1 = c.2 AND p.5 = 'unknown_error' AND p.4 = c.4 AND (
                    c.6 = 409 AND p.3 IN ('world.events.create wait_created', 'world.events.create wait_completed', 'world.events.create step_started', 'world.events.create run_started')
                    OR c.6 = 410 AND p.3 = 'world.events.create run_started'
                    OR c.6 = 404 AND (c.3 = 'http GET' AND p.3 = 'world.hooks.getByToken'
                        OR c.3 = 'http POST' AND p.3 = 'world.events.create hook_received')), errors), errors) AS clients
        FROM baseline_workflow_traces
    ),
    baseline_handled_parents AS (
        SELECT service_name, trace_id, errors, clients,
            arrayFilter(p -> has(arrayMap(c -> c.2, clients), p.1), errors) AS parents
        FROM baseline_handled_attempts
    ),
    baseline_handled_spans AS (
        SELECT service_name, trace_id,
            arrayJoin(arrayConcat(
                arrayMap(c -> c.1, clients),
                arrayMap(p -> p.1, parents),
                arrayMap(g -> g.1, arrayFilter(g -> g.5 = 'unknown_error' AND (
                    g.3 = 'hook.resume' AND arrayExists(p -> p.2 = g.1 AND p.3 IN ('world.hooks.getByToken', 'world.events.create hook_received'), parents)
                    OR g.3 = 'workflow.replay.load' AND arrayExists(p -> p.2 = g.1 AND p.3 = 'world.events.create run_started', parents)), errors))
            )) AS span_id
        FROM baseline_handled_parents
    ),

    fixture_identities AS (
        SELECT DISTINCT r.1 AS case_id, concat(r.2, '/', r.3) AS identity,
            r.4 AS service_name, r.5 AS trace_id, r.6 AS span_id FROM fixture_rows
    ),
    fixture_actual AS (
        SELECT f.case_id AS case_id, groupUniqArray(f.identity) AS identities, count() AS raw_count
        FROM fixture_identities f JOIN handled_spans h
          ON f.service_name = h.service_name AND f.trace_id = h.trace_id AND f.span_id = h.span_id
        GROUP BY f.case_id
    ),
    fixture_baseline AS (
        SELECT f.case_id AS case_id, groupUniqArray(f.identity) AS identities, count() AS raw_count
        FROM fixture_identities f JOIN baseline_handled_spans h
          ON f.service_name = h.service_name AND f.trace_id = h.trace_id AND f.span_id = h.span_id
        GROUP BY f.case_id
    ),
    fixture_expected AS (SELECT arrayJoin([('case-001', ['duplicate-step/http', 'duplicate-step/sdk', 'duplicate-wait/http', 'duplicate-wait/sdk', 'expired/http', 'expired/sdk', 'expired/wrapper']),
('case-002', ['cron/http', 'cron/resume', 'cron/sdk', 'wake/http', 'wake/resume', 'wake/sdk']),
('case-003', []),
('case-004', []),
('case-005', []),
('case-006', []),
('case-007', []),
('case-008', []),
('case-009', []),
('case-010', []),
('case-011', []),
('case-012', []),
('case-013', []),
('case-014', []),
('case-015', ['legacy/http', 'legacy/sdk', 'legacy/wrapper']),
('case-016', ['queue-attempt/http', 'queue-attempt/sdk', 'queue-attempt/wrapper']),
('case-017', ['queue-attempt/http', 'queue-attempt/sdk', 'queue-attempt/wrapper']),
('case-018', []),
('case-019', []),
('case-020', []),
('case-021', []),
('case-022', []),
('case-023', []),
('case-024', []),
('case-025', []),
('case-026', []),
('case-027', []),
('case-028', []),
('case-029', []),
('case-030', []),
('case-031', []),
('case-032', []),
('case-033', []),
('case-034', ['shared/http', 'shared/sdk', 'shared/wrapper']),
('case-035', ['direct/http', 'direct/sdk']),
('case-036', ['trace/http', 'trace/sdk']),
('case-037', []),
('case-038', []),
('case-039', ['typed/http', 'typed/sdk']),
('case-040', ['wait-completed/http', 'wait-completed/sdk']),
('case-041', []),
('case-042', ['trace/http', 'trace/resume', 'trace/sdk']),
('case-043', ['trace/http', 'trace/resume', 'trace/sdk']),
('case-044', []),
('case-045', []),
('case-046', []),
('case-047', []),
('case-048', []),
('case-049', []),
('case-050', []),
('case-051', []),
('case-052', []),
('case-053', []),
('case-054', []),
('case-055', []),
('case-056', []),
('case-057', []),
('case-058', []),
('case-059', []),
('case-060', ['trace/http', 'trace/sdk']),
('case-061', ['shared-client/http', 'shared-client/http-retry', 'shared-client/sdk', 'shared-client/wrapper']),
('case-062', ['duplicate-row/http', 'duplicate-row/sdk', 'duplicate-row/wrapper']),
('case-063', ['own-success/http', 'own-success/sdk', 'own-success/wrapper']),
('case-064', ['historical-linked/http', 'historical-linked/sdk', 'historical-linked/wrapper'])]) AS expectation),
    fixture_results AS (
        SELECT tupleElement(e.expectation, 1) AS case_id,
            concat('ids:', arrayStringConcat(arraySort(coalesce(a.identities, [])), ',')) AS actual_ids,
            concat('ids:', arrayStringConcat(arraySort(coalesce(b.identities, [])), ',')) AS baseline_ids,
            concat('ids:', arrayStringConcat(arraySort(tupleElement(e.expectation, 2)), ',')) AS expected_ids,
            length(coalesce(a.identities, [])) AS distinct_count, coalesce(a.raw_count, 0) AS raw_count,
            length(coalesce(b.identities, [])) AS baseline_distinct_count, coalesce(b.raw_count, 0) AS baseline_raw_count,
            length(tupleElement(e.expectation, 2)) AS expected_count,
            if(arraySort(coalesce(a.identities, [])) = arraySort(tupleElement(e.expectation, 2)), 1, 0) AS passed,
            if(arraySort(coalesce(b.identities, [])) = arraySort(tupleElement(e.expectation, 2)), 1, 0) AS baseline_passed
        FROM fixture_expected e LEFT JOIN fixture_actual a ON a.case_id = tupleElement(e.expectation, 1)
        LEFT JOIN fixture_baseline b ON b.case_id = tupleElement(e.expectation, 1)
    )
SELECT case_id, actual_ids, baseline_ids, expected_ids, distinct_count, raw_count, baseline_distinct_count, baseline_raw_count,
    expected_count, passed, baseline_passed, 1 AS case_count FROM fixture_results
UNION ALL
SELECT '__summary__' AS case_id, 'ids:' AS actual_ids, 'ids:' AS baseline_ids, 'ids:' AS expected_ids,
    sum(distinct_count) AS distinct_count, sum(raw_count) AS raw_count,
    sum(baseline_distinct_count) AS baseline_distinct_count, sum(baseline_raw_count) AS baseline_raw_count,
    sum(expected_count) AS expected_count, min(passed) AS passed, min(baseline_passed) AS baseline_passed, count() AS case_count FROM fixture_results
ORDER BY case_id